"""

import json
import logging
from typing import Any

from .model import Model

logger = logging.getLogger(__name__)

class LlamaCppModel(Model):
    def __init__(self, model_id: str = "default", params: dict[str, Any] | None = None) -> None:
        self.config = {"model_id": model_id, "params": params or {}}

    def _format_request(self, messages: list[dict[str, Any]], tool_specs=None, system_prompt: str | None = None) -> dict[str, Any]:
        request = {
            "messages": self._format_messages(messages, system_prompt),
            "model": self.config["model_id"],
            "stream": True,
            "stream_options": {"include_usage": True},
            "tools": [
                {
                    "type": "function",
                    "function": {
                        "name": tool_spec["name"],
                        "description": tool_spec["description"],
                        "parameters": tool_spec["inputSchema"]["json"],
                    },
                }
                for tool_spec in tool_specs or []
            ],
        }

        params = self.config.get("params")
        if params and isinstance(params, dict):
            # Grammar and json_schema go directly in request body
            if "grammar" in params:
                request["grammar"] = params["grammar"]
            if "json_schema" in params:
                request["json_schema"] = params["json_schema"]

            llamacpp_specific_params = {
                "repeat_penalty",
                "top_k",
                "min_p",
                "typical_p",
