                "cache_prompt",
                "slot_id",
                "samplers",
            }

            openai_params = {
                "temperature",
                "max_tokens",
                "top_p",
                "frequency_penalty",
                "presence_penalty",
                "stop",
                "seed",
                "n",
                "logprobs",
                "top_logprobs",
                "response_format",
            }

            for param, value in params.items():
                if param in openai_params:
                    request[param] = value

            extra_body = {}
            for param, value in params.items():
                if param in llamacpp_specific_params:
                    extra_body[param] = value

            if extra_body:
                request.update(extra_body)

        return request

